using MyPiggyBank.Core;
using System.Text.Json;

internal static class SelfDebtChecks
{
    private static readonly DateOnly Start=new(2026,10,1);
    private static readonly Bank A=new(Guid.NewGuid(),"BCA",Start,3_000_000),B=new(Guid.NewGuid(),"OCBC",Start,2_000_000);
    private static readonly Category Salary=new(Guid.NewGuid(),"Salary",CategoryKind.Income),Food=new(Guid.NewGuid(),"Shopping",CategoryKind.Expense);
    private static readonly Purpose Repay=new(Guid.NewGuid(),"Debt Repayment"),Savings=new(Guid.NewGuid(),"Savings");
    private static readonly Guid Id=Guid.NewGuid();
    private static Debt Self()=>new(Id,"RAM purchase","",null,Kind:DebtKind.Self,SelfBankId:A.Id);
    private static FinanceDocument Empty()=>new(){Banks=[A,B],Categories=[Salary,Food]};
    private static Transaction Origin()=>new(Guid.NewGuid(),new(2026,10,4),TransactionKind.Expense,A.Id,null,Food.Id,2_000_000,2500,null,"RAM",DebtId:Id);
    private static Transaction Income(decimal repay=500_000)=>new(Guid.NewGuid(),new(2026,10,10),TransactionKind.Income,A.Id,null,Salary.Id,1_000_000,2500,null,"Salary",SelfDebtPayment:new(Id,repay));
    private static Transaction Transfer()=>new(Guid.NewGuid(),new(2026,10,15),TransactionKind.Transfer,B.Id,A.Id,null,1_000_000,2500,null,"Restore savings",[new(Repay.Id,500_000,Id),new(Savings.Id,500_000)]);
    private static FinanceDocument Ready()=>DebtService.SaveTransaction(Empty(),Origin(),Self());
    private static FinanceDocument Partial()=>DebtService.SaveTransaction(Ready(),Income());
    private static FinanceDocument Split(){var d=Partial();d.Purposes=[Repay,Savings];return DebtService.SaveTransaction(d,Transfer());}
    private static FinanceDocument Settled()=>DebtService.SaveTransaction(Split(),Income(1_000_000) with{Date=new(2026,10,20),Fee=0});
    private static void Equal<T>(T expected,T actual){if(!EqualityComparer<T>.Default.Equals(expected,actual))throw new Exception($"Expected {expected}, got {actual}");}
    private static void Reject(Action action){try{action();}catch(InvalidDataException){return;}throw new Exception("Expected rejection");}
    public static FinanceDocument Fixture()
    {
        var d=Split();d.Transactions.Add(Origin() with{Amount=60_000,Fee=0,DebtId=null,Date=new(2026,10,3),Description="Historical Expense to track"});d.Validate();return d;
    }
    public static void Run(Action<string,Action> test)
    {
        test("Self Debt tags an old Expense without duplicating cash or reports",()=>{var d=Empty();var tx=Origin() with{DebtId=null};d.Transactions.Add(tx);var cash=d.Balance(A.Id);var report=d.Totals(Start,new(2026,10,31));d=DebtService.SaveTransaction(d,tx with{DebtId=Id},Self());Equal(1,d.Transactions.Count);Equal(cash,d.Balance(A.Id));Equal(report,d.Totals(Start,new(2026,10,31)));Equal(new DebtTotals(2_000_000,0),d.DebtAmounts(Id));Equal("RAM purchase · Self Debt · BCA",d.DebtLabel(Id));});
        test("Self Debt origin fee is excluded from principal",()=>{var d=Ready();Equal(997_500m,d.Balance(A.Id));Equal(2_000_000m,d.DebtAmounts(Id).Borrowed);Equal(DebtStatus.Open,d.DebtState(Id));Equal(d.Balance(A.Id),d.AvailableBalance(A.Id));});
        test("Self Debt can receive another Expense in its original bank",()=>{var d=DebtService.SaveTransaction(Ready(),Origin() with{Amount=100_000,Date=new(2026,10,5)});Equal(2_100_000m,d.DebtAmounts(Id).Remaining);});
        test("Self Debt origins cannot switch accounts",()=>{var d=Ready();Reject(()=>DebtService.SaveTransaction(d,d.Transactions.Single() with{BankId=B.Id}));});
        test("Self Debt requires an original Expense not synthetic Income",()=>{Reject(()=>DebtService.SaveTransaction(Empty(),Income() with{DebtId=Id,SelfDebtPayment=null},Self()));var d=Ready();d.Transactions.Clear();Reject(d.Validate);});
        test("Income repayment uses only the explicitly marked part",()=>{var d=Partial();Equal(new DebtTotals(2_000_000,500_000),d.DebtAmounts(Id));Equal(1_995_000m,d.Balance(A.Id));Equal((1_000_000m,2_005_000m),d.Totals(Start,new(2026,10,31)));Equal(DebtStatus.PartiallyPaid,d.DebtState(Id));});
        test("unmarked Income does not silently repay Self Debt",()=>{var d=DebtService.SaveTransaction(Ready(),Income() with{SelfDebtPayment=null});Equal(0m,d.DebtAmounts(Id).Paid);});
        test("both Income fee bases cap Self Debt repayment at net received",()=>{var a=DebtService.SaveTransaction(Ready(),Income(997_500));var b=DebtService.SaveTransaction(Ready(),Income(997_500) with{Amount=997_500,IncomeBasis=IncomeAmountBasis.AfterFee});Equal(a.DebtAmounts(Id),b.DebtAmounts(Id));Equal(a.Balance(A.Id),b.Balance(A.Id));Reject(()=>DebtService.SaveTransaction(Ready(),Income(997_501)));Reject(()=>DebtService.SaveTransaction(Ready(),Income(997_501) with{Amount=997_500,IncomeBasis=IncomeAmountBasis.AfterFee}));});
        test("Self Debt Income repayment requires original receiving bank",()=>Reject(()=>DebtService.SaveTransaction(Ready(),Income() with{BankId=B.Id})));
        test("Self Debt repayment rejects zero negative fractional and excessive amounts",()=>{foreach(var amount in new[]{0m,-1m,1.001m,1_000_000m})Reject(()=>DebtService.SaveTransaction(Ready(),Income(amount)));});
        test("Expense cannot be used as a direct Self Debt repayment",()=>Reject(()=>DebtService.SaveTransaction(Ready(),Origin() with{DebtId=null,SelfDebtPayment=new(Id,100)})));
        test("external and Self Debt tracking coexist without mixing roles",()=>{var d=Ready();var external=new Debt(Guid.NewGuid(),"Loan","Alex",null);var tx=Income() with{SelfDebtPayment=null,DebtId=external.Id};d=DebtService.SaveTransaction(d,tx,external);Reject(()=>DebtService.SaveTransaction(d,tx with{SelfDebtPayment=new(Id,100)}));Equal(1_000_000m,d.DebtAmounts(external.Id).Borrowed);Equal(0m,d.DebtAmounts(Id).Paid);});
        test("direct Self Debt repayment cannot target an external lender",()=>{var d=Empty();var external=new Debt(Guid.NewGuid(),"Loan","Alex",null);d=DebtService.SaveTransaction(d,Income() with{SelfDebtPayment=null,DebtId=external.Id},external);Reject(()=>DebtService.SaveTransaction(d,Income() with{SelfDebtPayment=new(external.Id,100)}));});
        test("split transfer repays only the linked purpose amount",()=>{var d=Split();Equal(new DebtTotals(2_000_000,1_000_000),d.DebtAmounts(Id));Equal(2_995_000m,d.Balance(A.Id));Equal(997_500m,d.Balance(B.Id));Equal((1_000_000m,2_007_500m),d.Totals(Start,new(2026,10,31)));Equal(3,d.Transactions.Count);Equal(true,d.AllocationSummary(d.Transactions.Last()).Contains("RAM purchase"));Equal(true,d.RelatedDebtIds(d.Transactions.Last()).Contains(Id));});
        test("purpose name alone never counts as debt repayment",()=>{var d=Partial();d.Purposes=[Repay,Savings];d=DebtService.SaveTransaction(d,Transfer() with{Allocations=[new(Repay.Id,1_000_000)]});Equal(500_000m,d.DebtAmounts(Id).Paid);});
        test("repayment transfer must reach the original account",()=>{var d=Split();var tx=d.Transactions.Last();Reject(()=>DebtService.SaveTransaction(d,tx with{BankId=A.Id,ToBankId=B.Id}));});
        test("repayment links must identify an existing Self Debt",()=>{Reject(()=>DebtService.SaveTransaction(Ready(),Income() with{SelfDebtPayment=new(Guid.NewGuid(),100)}));var d=Partial();d.Purposes=[Repay];Reject(()=>DebtService.SaveTransaction(d,Transfer() with{Allocations=[new(Repay.Id,1_000_000,Guid.NewGuid())]}));});
        test("one transfer can repay distinct Self Debts under one purpose",()=>{var other=Self() with{Id=Guid.NewGuid(),Name="Chair"};var d=DebtService.SaveTransaction(Ready(),Origin() with{Amount=200_000,DebtId=other.Id},other);d.Purposes=[Repay];var tx=Transfer() with{Allocations=[new(Repay.Id,800_000,Id),new(Repay.Id,200_000,other.Id)]};d=DebtService.SaveTransaction(d,tx);Equal(800_000m,d.DebtAmounts(Id).Paid);Equal(200_000m,d.DebtAmounts(other.Id).Paid);Reject(()=>DebtService.SaveTransaction(d,tx with{Allocations=[new(Repay.Id,500_000,Id),new(Repay.Id,500_000,Id)]}));});
        test("Self Debt repayments cannot precede supporting expenses",()=>Reject(()=>DebtService.SaveTransaction(Ready(),Income() with{Date=new(2026,10,3)})));
        test("historic origin edits validate later Self Debt repayments",()=>{var d=Split();Reject(()=>DebtService.SaveTransaction(d,d.Transactions.First() with{Date=new(2026,10,16)}));Reject(()=>DebtService.SaveTransaction(d,d.Transactions.First() with{Amount=499_999}));});
        test("Self Debt overpayment rejection is atomic",()=>{var d=Settled();var json=JsonSerializer.Serialize(d);Reject(()=>DebtService.SaveTransaction(d,Income(100) with{Date=new(2026,10,21)}));Equal(json,JsonSerializer.Serialize(d));});
        test("Self Debt reaches Pending Confirmation then manual Paid",()=>{var d=Settled();Equal(DebtStatus.PendingConfirmation,d.DebtState(Id));var count=d.Transactions.Count;d=DebtService.SetPaid(d,Id,true);Equal(DebtStatus.Paid,d.DebtState(Id));Equal(count,d.Transactions.Count);});
        test("Paid Self Debt must reopen before another original Expense",()=>{var d=DebtService.SetPaid(Settled(),Id,true);var tx=Origin() with{Amount=50_000,Date=new(2026,10,21)};Reject(()=>DebtService.SaveTransaction(d,tx));d=DebtService.SetPaid(d,Id,false);d=DebtService.SaveTransaction(d,tx);Equal(50_000m,d.DebtAmounts(Id).Remaining);});
        test("Paid Self Debt rejects removing a repayment link",()=>{var d=DebtService.SetPaid(Settled(),Id,true);Reject(()=>DebtService.SaveTransaction(d,d.Transactions.Last() with{SelfDebtPayment=null}));var copy=d.Copy();copy.Transactions.RemoveAt(copy.Transactions.Count-1);Reject(copy.Validate);});
        test("unmarking a transfer repayment retains its bank transaction",()=>{var d=Split();var tx=d.Transactions.Last();var cash=d.Banks.Sum(b=>d.Balance(b.Id));var report=d.Totals(Start,new(2026,10,31));d=DebtService.SaveTransaction(d,tx with{Allocations=tx.Allocations!.Select(a=>a with{SelfDebtId=null}).ToArray()});Equal(500_000m,d.DebtAmounts(Id).Paid);Equal(cash,d.Banks.Sum(b=>d.Balance(b.Id)));Equal(report,d.Totals(Start,new(2026,10,31)));});
        test("relinking a repayment validates both Self Debt histories",()=>{var d=Partial();var other=Self() with{Id=Guid.NewGuid(),Name="Small item"};d=DebtService.SaveTransaction(d,Origin() with{Amount=100_000,DebtId=other.Id},other);Reject(()=>DebtService.SaveTransaction(d,d.Transactions.Single(t=>t.SelfDebtPayment is not null) with{SelfDebtPayment=new(other.Id,500_000)}));});
        test("last Self Debt origin cannot be deleted or untracked",()=>{var d=Partial();Reject(()=>DebtService.SaveTransaction(d,d.Transactions.First() with{DebtId=null}));var copy=d.Copy();copy.Transactions.RemoveAt(0);Reject(copy.Validate);});
        test("Remove Tracking retains bank ledger and purpose splits",()=>{var d=Split();var cash=d.Banks.Sum(b=>d.Balance(b.Id));var report=d.Totals(Start,new(2026,10,31));d=DebtService.RemoveTracking(d,Id);Equal(0,d.Debts.Count);Equal(3,d.Transactions.Count);Equal(true,d.Transactions.All(t=>!d.RelatedDebtIds(t).Any()));Equal(2,d.Transactions.Last().Allocations!.Count);Equal(1_000_000m,d.Transactions.Last().Allocations!.Sum(a=>a.Amount));Equal(cash,d.Banks.Sum(b=>d.Balance(b.Id)));Equal(report,d.Totals(Start,new(2026,10,31)));});
        test("Self Debt details preserve its fixed account",()=>{var d=DebtService.EditDetails(Ready(),Id,"Updated RAM","",DateOnly.FromDateTime(DateTime.Today).AddDays(10));Equal<Guid?>(A.Id,d.Debts.Single().SelfBankId);Equal(false,d.DebtOverdue(Id));Reject(()=>DebtService.EditDetails(d,Id,"RAM","Alex",null));});
        test("Self Debt validates kind lender and original bank",()=>{foreach(var invalid in new[]{Self() with{SelfBankId=null},Self() with{SelfBankId=Guid.NewGuid()},Self() with{Kind=(DebtKind)99},Self() with{Lender="Alex"}})Reject(()=>DebtService.SaveTransaction(Empty(),Origin(),invalid));});
        test("format seven cannot claim Self Debt semantics",()=>{var d=Ready();d.Version=7;Reject(d.Validate);var plain=Empty();plain.Version=7;plain.Transactions.Add(Income());Reject(plain.Validate);});
        test("future Self Debt origins and repayments are rejected",()=>{var future=DateOnly.FromDateTime(DateTime.Today).AddDays(1);Reject(()=>DebtService.SaveTransaction(Empty(),Origin() with{Date=future},Self()));Reject(()=>DebtService.SaveTransaction(Ready(),Income() with{Date=future}));});
        test("same-day Self Debt is evaluated as dated aggregates",()=>{var d=Ready();d.Transactions.Insert(0,Income(1_000_000) with{Fee=0,Date=new(2026,10,4)});d.Validate();Equal(1_000_000m,d.DebtAmounts(Id).Remaining);});
        test("copy isolates Self Debt origin and repayment links",()=>{var d=Split();var copy=d.Copy();copy.Transactions[2]=copy.Transactions[2] with{Allocations=copy.Transactions[2].Allocations!.Select(a=>a with{SelfDebtId=null}).ToArray()};Equal(1_000_000m,d.DebtAmounts(Id).Paid);Equal(500_000m,copy.DebtAmounts(Id).Paid);});
        test("removing one Self Debt retains unrelated repayment splits",()=>{var other=Self() with{Id=Guid.NewGuid(),Name="Chair"};var d=DebtService.SaveTransaction(Ready(),Origin() with{Amount=200_000,DebtId=other.Id},other);d.Purposes=[Repay];d=DebtService.SaveTransaction(d,Transfer() with{Allocations=[new(Repay.Id,800_000,Id),new(Repay.Id,200_000,other.Id)]});d=DebtService.RemoveTracking(d,Id);Equal(200_000m,d.DebtAmounts(other.Id).Paid);Equal(2,d.Transactions.Last().Allocations!.Count);});
        var folder=Path.Combine(Path.GetTempPath(),"MyPiggyBank-SelfDebt-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);
        try{
            test("Self Debt origin Income and split Transfer survive Save Open",()=>{var file=Path.Combine(folder,"self.mpb");var session=new DocumentSession();session.Apply(Split());session.Save(file);var bytes=File.ReadAllBytes(file);session.Apply(DebtService.EditDetails(session.Document,Id,"Renamed","",null));Equal(true,bytes.SequenceEqual(File.ReadAllBytes(file)));session.Save(file);var again=new DocumentSession();again.Open(file);Equal(FinanceDocument.CurrentVersion,again.Document.Version);Equal(new DebtTotals(2_000_000,1_000_000),again.Document.DebtAmounts(Id));Equal(3,again.Document.Transactions.Count);Equal(DebtKind.Self,again.Document.Debts.Single().Kind);Equal(500_000m,again.Document.Transactions.Last().Allocations!.Single(a=>a.SelfDebtId==Id).Amount);});
            test("format seven lender debts open without reinterpretation or rewrite",()=>{var file=Path.Combine(folder,"seven.mpb");var d=Empty();var external=new Debt(Guid.NewGuid(),"Old loan","Alex",null);d=DebtService.SaveTransaction(d,Income() with{SelfDebtPayment=null,DebtId=external.Id},external);d.Version=7;var node=System.Text.Json.Nodes.JsonNode.Parse(JsonSerializer.Serialize(d))!;foreach(var item in node["Debts"]!.AsArray()){item!.AsObject().Remove("Kind");item.AsObject().Remove("SelfBankId");}foreach(var tx in node["Transactions"]!.AsArray())tx!.AsObject().Remove("SelfDebtPayment");File.WriteAllText(file,node.ToJsonString());var bytes=File.ReadAllBytes(file);var session=new DocumentSession();session.Open(file);Equal(FinanceDocument.CurrentVersion,session.Document.Version);Equal(DebtKind.External,session.Document.Debts.Single().Kind);Equal(1_000_000m,session.Document.DebtAmounts(external.Id).Borrowed);Equal(true,bytes.SequenceEqual(File.ReadAllBytes(file)));Equal(false,session.Dirty);});
        }finally{Directory.Delete(folder,true);}
    }
}
